="mb-3"><h5 class="mb-1">تعریف کالای جدید برای برگشت سازه‌حساب</h5><div class="sr-muted small">کالا و تنوع‌ها پس از ثبت نهایی سند ساخته می‌شوند. تصویر موقت در این مودال پشتیبانی نمی‌شود تا فایل بدون سند در Public رها نشود.</div></div><div class="np-grid"><div class="card-soft"><div class="section-head">اطلاعات پایه و دسته‌بندی</div><label class="form-label">نام کالا <span class="text-danger">*</span></label><input class="form-control form-control-sm mb-2 np-field" id="npName"><div class="row g-2"><div class="col-md-6"><label class="form-label">واحد پیش‌فرض</label><input class="form-control form-control-sm np-field" id="npUnit" value="عدد"></div><div class="col-md-6"><label class="form-label">قابل فروش</label><select class="form-select form-select-sm np-field" id="npSales"><option value="1">فعال</option><option value="0">قابل بازبینی/غیرفعال</option></select></div></div><div class="tree-box mt-3"><div class="d-flex justify-content-between align-items-center mb-2"><strong>دسته‌بندی درختی</strong><button class="btn btn-sm btn-outline-primary" type="button" id="npQuickCategory">+ افزودن دسته‌بندی جدید</button></div><div class="row g-2" id="npCategoryLevels"></div><div class="np-field-error" id="npCategoryError"></div><div class="mt-2"><span id="npCategoryBreadcrumb" class="tree-breadcrumb">دسته‌بندی انتخاب نشده است</span></div></div><div class="preview-box mt-3"><div class="small sr-muted mb-2" id="npCodeHint">پس از انتخاب دسته‌بندی، کد کالا نمایش داده می‌شود.</div><div class="row g-2"><div class="col"><div class="mini-stat">شماره ترتیبی<br><strong id="npSeqPreview">{{ str_pad((string)((int)\App\Models\Product::max('id') + 1), 4, '0', STR_PAD_LEFT) }}</strong></div></div><div class="col"><div class="mini-stat">کد کالا<br><strong id="npProductCodePreview">—</strong></div></div><div class="col"><div class="mini-stat">الگوی تنوع<br><strong id="npVariantCodePreview">—</strong></div></div></div></div></div><div class="card-soft model-picker"><div class="section-head">مدل‌لیست</div><div class="form-check form-switch mb-2"><input class="form-check-input np-field" type="checkbox" id="npUseModels"><label class="form-check-label fw-bold" for="npUseModels">این کالا مدل‌لیست دارد</label></div><div id="npModelPanel" class="picker-panel d-none"><label class="form-label">گروه برند</label><select class="form-select form-select-sm mb-2 np-field" id="npModelBrand"><option value="">انتخاب برند</option></select><div class="input-group input-group-sm mb-2"><input class="form-control np-field" id="npModelSearch" placeholder="جستجو با نام یا کد"><button class="btn btn-outline-primary" type="button" id="npQuickModel">+ افزودن مدل جدید</button></div><div class="d-flex gap-2 mb-2"><button type="button" class="btn btn-sm btn-outline-secondary" id="npSelectFilteredModels">انتخاب همه نتایج</button><button type="button" class="btn btn-sm btn-outline-danger" id="npClearModels">پاک‌کردن همه</button><span class="small sr-muted me-auto"><span id="npSelectedModelCount">0</span> مدل انتخاب‌شده</span></div><div id="npModelTags" class="d-flex flex-wrap gap-1 mb-2"></div><div class="picker-list" id="npModelList"></div></div></div><div class="card-soft np-design-card"><div class="section-head">طرح‌بندی</div><div class="form-check form-switch mb-2"><input class="form-check-input np-field" type="checkbox" id="npUseDesigns"><label class="form-check-label fw-bold" for="npUseDesigns">این کالا طرح‌بندی دارد</label></div><div id="npDesignPanel" class="d-none"><label class="form-label">تعداد طرح</label><input type="number" min="1" max="99" class="form-control form-control-sm mb-2 np-field" id="npDesignCount" value="1"><div id="npDesignRows" class="np-design-grid"></div><div class="np-field-error" id="npDesignError"></div></div></div><div class="card-soft"><div class="section-head">قیمت‌ها (ریال)</div><div class="np-price-grid"><div><label class="form-label">قیمت خرید فعلی</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npPurchase" autocomplete="off"><div class="np-field-error" data-price-error="npPurchase"></div></div><div><label class="form-label">قیمت فروش فعلی</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npSell" autocomplete="off"><div class="np-field-error" data-price-error="npSell"></div></div><div><label class="form-label">قیمت برگشتی پیش‌فرض مشتری</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npRefund" autocomplete="off"><div class="np-field-error" data-price-error="npRefund"></div></div></div><div class="preview-box mt-3"><div class="np-summary-strip"><div><span>کل: </span><strong id="npTotalVariants">1</strong></div><div><span>انتخاب‌شده: </span><strong id="npPickedVariants">1</strong></div><div><span>حذف‌شده: </span><strong id="npUnpickedVariants">0</strong></div></div></div></div><div class="card-soft mt-3 sr-variant-preview"><div class="section-head">پیش‌نمایش تنوع‌های قابل ساخت</div><div class="sr-variant-preview__viewport"><div class="sr-variant-preview__header"><div>انتخاب</div><div>نام تنوع</div><div>مدل</div><div>طرح</div><div>کد نمونه</div><div>خرید</div><div>فروش</div><div>برگشتی</div></div><div id="npVariantPreview"></div></div><div class="np-field-error" id="npVariantError"></div><div class="text-danger small d-none" id="npErrors"></div></div></div>@endcan</div></div></div><div class="modal-footer"><div class="sr-modal__footer"><span class="small sr-muted">انتخاب‌شده: <strong id="npFooterSelected">0</strong> | مبلغ برگشتی پیش‌فرض: <strong id="npFooterRefund">0</strong> ریال</span><div class="sr-modal__footer-actions"><button class="btn btn-outline-secondary btn-sm" type="button" data-bs-dismiss="modal">انصراف</button>@can('sales_returns.create_product')<button class="btn btn-primary btn-sm" type="button" id="addNewProductRow" disabled>افزودن تنوع‌های انتخاب‌شده</button>@endcan</div></div></div></div></div>
<script>
window.salesReturnRoutes = @json($salesReturnRoutes);
window.salesReturnInitial = {items:@json($initialItems), sourceType:@json(old('source_type', $document?->source_type ?? 'internal_invoice')), customerId:@json(old('customer_id', $document?->customer_id)), invoiceId:@json(old('invoice_id', $document?->invoice_id)), warehouses:@json($warehouses->map(fn($w)=>['id'=>$w->id,'name'=>$w->name,'type'=>$w->type])->values()), categories:@json($categories->values()), modelLists:@json($modelLists->values())};
</script>
<script>
(() => {
const routes=window.salesReturnRoutes, init=window.salesReturnInitial;
const state={type:init.sourceType||'internal_invoice',customer:{id:init.customerId||null,name:'',mobile:'',code:''},invoice:null,externalInvoiceDate:document.getElementById('externalInvoiceDate')?.value||'',internalItems:[],sazehItems:[],newProducts:[],newProduct:{prices:{purchase:null,sell:null,refund:null}},selectedCategories:[],selectedProducts:{},selectedVariants:new Map(),defaultDestinationWarehouseId:document.getElementById('defaultWarehouse').value,summary:{},items:init.items||[]};
let customerAbort, invoiceAbort, customerRequest=0, invoiceRequest=0, customerActive=-1, productAbort, categoryProductAbort, customerTimer, productTimer;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const faDigits='۰۱۲۳۴۵۶۷۸۹', enDigits='0123456789';
const toPersianDigits=v=>String(v??'').replace(/[0-9]/g,d=>faDigits[d]);
const toEnglishDigits=v=>String(v??'').replace(/[۰-۹]/g,d=>String(faDigits.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const sanitizeMoneyInput=v=>toEnglishDigits(v).replace(/(ریال|تومان)/g,'').replace(/[,،.\s]/g,'').replace(/[^0-9]/g,'');
const moneyToInteger=v=>{const clean=sanitizeMoneyInput(v);return clean===''?null:parseInt(clean,10)};
const rawNumber=v=>moneyToInteger(v)??0;
const fmt=n=>{const value=typeof n==='number'?n:moneyToInteger(n);return value===null?'':value.toLocaleString('fa-IR')};
const moneyText=n=>(fmt(n)||'۰')+' ریال';
const fmtDate=d=>formatJalaliDate(d)||'—';
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const whName=id=>(init.warehouses.find(w=>String(w.id)===String(id))||{}).name||'—';
function gregorianToJalali(gy,gm,gd){const g_d_m=[0,31,59,90,120,151,181,212,243,273,304,334];let jy=(gy<=1600)?0:979;gy-=(gy<=1600)?621:1600;const gy2=(gm>2)?gy+1:gy;let days=(365*gy)+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)-80+gd+g_d_m[gm-1];jy+=33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365}const jm=(days<186)?1+Math.floor(days/31):7+Math.floor((days-186)/30);const jd=1+((days<186)?(days%31):((days-186)%30));return [jy,jm,jd]}
function formatJalaliDate(value){if(!value)return'';const m=toEnglishDigits(value).match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);if(!m)return toPersianDigits(value);const [jy,jm,jd]=gregorianToJalali(+m[1],+m[2],+m[3]);return toPersianDigits(`${jy}/${String(jm).padStart(2,'0')}/${String(jd).padStart(2,'0')}`)}
function jalaliToGregorian(jy,jm,jd){jy=Number(jy);jm=Number(jm);jd=Number(jd);jy+=(jy<100)?1400:0;let gy=jy<=979?621:1600;let y=jy<=979?jy:jy-979;let days=365*y+Math.floor(y/33)*8+Math.floor(((y%33)+3)/4)+78+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);gy+=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365}let gd=days+1;const sal=[0,31,((gy%4===0&&gy%100!==0)||gy%400===0)?29:28,31,30,31,30,31,31,30,31,30,31];let gm=1;while(gm<=12&&gd>sal[gm]){gd-=sal[gm];gm++}return [gy,gm,gd]}
function normalizeJalaliDateInput(v){const normalized=toEnglishDigits(v).trim().replace(/\s+/g,'').replace(/-/g,'/');if(normalized==='')return'';const m=normalized.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!m)return null;const jy=+m[1],jm=+m[2],jd=+m[3];if(jm<1||jm>12||jd<1||jd>31)return null;const [gy,gm,gd]=jalaliToGregorian(jy,jm,jd);return `${gy}-${String(gm).padStart(2,'0')}-${String(gd).padStart(2,'0')}`}
function syncExternalDateDisplay(){const raw=$('#externalInvoiceDate')?.value;const fa=$('#externalInvoiceDateFa');if(fa&&raw)fa.value=formatJalaliDate(raw)}
function syncExternalDateFromVisible(showError=false){const fa=$('#externalInvoiceDateFa'), hidden=$('#externalInvoiceDate'), err=$('#externalInvoiceDateError');if(!fa||!hidden)return true;const parsed=normalizeJalaliDateInput(fa.value);if(parsed===null){if(showError&&err)err.textContent='تاریخ را به‌شکل ۱۴۰۵/۰۴/۲۲ وارد کنید.';return false}hidden.value=parsed;state.externalInvoiceDate=parsed;if(err)err.textContent='';return true}
function initSazehInvoiceDatePicker(){const input=$('#externalInvoiceDateFa');if(!input)return;input.disabled=state.type!=='sazeh_hesab';input.readOnly=false;if(input.dataset.datepickerInitialized==='1')return;input.dataset.datepickerInitialized='1';if(window.jalaliDatepicker){window.jalaliDatepicker.startWatch({selector:'#externalInvoiceDateFa',persianDigits:true,zIndex:3000});input.addEventListener('jdp:change',()=>syncExternalDateFromVisible(false));}}

function syncSource(){state.type=$('#sourceTypeInput').value=state.type;$$('[data-source-choice]').forEach(el=>el.classList.toggle('active',el.dataset.sourceChoice===state.type));$$('[name=source_choice]').forEach(r=>r.checked=r.value===state.type);$$('.sazeh-only').forEach(el=>el.classList.toggle('d-none',state.type!=='sazeh_hesab'));$$('.internal-only,.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));initSazehInvoiceDatePicker();if(state.type==='internal_invoice'&&state.customer.id)loadCustomerInvoices(state.customer.id);renderItems();}
function setSource(type){if(type===state.type)return;if(state.items.length&&!confirm('با تغییر نوع برگشت، اقلام فعلی پاک می‌شوند. ادامه می‌دهید؟')){syncSource();return}state.type=type;state.invoice=null;$('#invoiceId').value='';state.items=[];if(type!=='internal_invoice')resetInvoiceSelect('فاکتور داخلی فقط در نوع فاکتور داخلی بارگذاری می‌شود.', true);syncSource();}
function hiddenInputs(it,i){const parts=[];const input=(name,v)=>parts.push(`<input type="hidden" name="${name}" value="${esc(v)}">`);const h=(k,v)=>input(`items[${i}][${k}]`,v);const nested=(base,val)=>{if(Array.isArray(val)){val.forEach((v,idx)=>nested(`${base}[${idx}]`,v));return}if(val&&typeof val==='object'){Object.entries(val).forEach(([k,v])=>nested(`${base}[${k}]`,v));return}input(base,val??'')};h('item_source',it.item_source);h('invoice_item_id',it.invoice_item_id||'');h('product_variant_id',it.product_variant_id||'');h('return_quantity',it.return_quantity||1);h('item_condition',it.item_condition||'healthy');h('destination_warehouse_id',it.destination_warehouse_id||state.defaultDestinationWarehouseId||'');h('refund_unit_price',it.refund_unit_price||0);h('purchase_price',it.purchase_price||'');h('sell_price',it.sell_price||'');if(it.new_product_payload)nested(`items[${i}][new_product_payload]`,it.new_product_payload);return parts.join('')}
function rowName(it){return `${it.product_name||it.new_product_payload?.product_name||'—'} / ${it.variant_name||it.new_product_payload?.variant_name||'—'}`}
function whOptions(selected){return init.warehouses.map(w=>`<option value="${w.id}" data-type="${esc(w.type)}" ${String(selected||'')===String(w.id)?'selected':''}>${esc(w.name)}</option>`).join('')}
function markManualDestination(it){it.destination_touched=true}
function updateRowAmount(i){const it=state.items[i];if(!it)return;const amount=Number(it.return_quantity||0)*Number(it.refund_unit_price||0);it.refund_amount=amount;document.querySelectorAll(`[data-row-amount="${i}"]`).forEach(el=>el.textContent=fmt(amount)||'۰');summary()}
function normalizeRowDestination(it){if(!it.destination_warehouse_id)it.destination_warehouse_id=state.defaultDestinationWarehouseId||defaultWhFor(it.item_condition||'healthy');return it}
function renderItems(){const tb=$('#itemsTable tbody');tb.innerHTML='';$('#mobileItems').innerHTML='';state.items.forEach((it,i)=>{normalizeRowDestination(it);const max=state.type==='internal_invoice'?(it.returnable||1):999999;it.return_quantity=Math.max(1,Math.min(Number(it.return_quantity||1),max));it.refund_unit_price=rawNumber(it.refund_unit_price||0);it.refund_amount=it.return_quantity*Number(it.refund_unit_price||0);const warn=(it.item_condition==='healthy'&&whName(it.destination_warehouse_id).includes('مرجوع'))||(it.item_condition==='damaged'&&!whName(it.destination_warehouse_id).includes('مرجوع'));const tr=document.createElement('tr');tr.innerHTML=`<td>${hiddenInputs(it,i)}<strong>${esc(rowName(it))}</strong><div class="small sr-muted">${it.item_source==='new_product'?'کالای جدید؛ ساخت در ثبت نهایی':it.item_source==='existing_product'?'کالای موجود':'آیتم فاکتور'}</div></td><td>${esc(it.sku||it.barcode||it.new_product_payload?.sku||'—')}</td><td class="internal-col">${it.sold_quantity??'—'}</td><td class="internal-col">${it.previously_returned??'—'}</td><td class="internal-col">${it.returnable??'—'}</td><td><input class="form-control form-control-sm qty" data-i="${i}" type="number" min="1" max="${max}" value="${it.return_quantity}"></td><td><select class="form-select form-select-sm cond" data-i="${i}"><option value="healthy" ${it.item_condition==='healthy'?'selected':''}>سالم</option><option value="damaged" ${it.item_condition==='damaged'?'selected':''}>معیوب / مرجوعی</option></select></td><td><select class="form-select form-select-sm wh" data-i="${i}">${whOptions(it.destination_warehouse_id)}</select>${warn?'<div class="small text-warning">مقصد با وضعیت معمول کالا متفاوت است.</div>':''}</td><td>${state.type==='internal_invoice'?fmt(it.refund_unit_price):`<input class="form-control form-control-sm price" data-i="${i}" type="text" inputmode="numeric" value="${fmt(it.refund_unit_price)||''}">`}</td><td data-row-amount="${i}">${fmt(it.refund_amount)}</td><td><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></td>`;tb.appendChild(tr);$('#mobileItems').insertAdjacentHTML('beforeend',`<div class="border rounded p-2 mb-2"><div class="d-flex justify-content-between"><strong>${esc(rowName(it))}</strong><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></div><div class="small sr-muted">تعداد: <input class="form-control form-control-sm qty my-1" data-i="${i}" type="number" min="1" max="${max}" value="${it.return_quantity}"> وضعیت: <select class="form-select form-select-sm cond my-1" data-i="${i}"><option value="healthy" ${it.item_condition==='healthy'?'selected':''}>سالم</option><option value="damaged" ${it.item_condition==='damaged'?'selected':''}>معیوب / مرجوعی</option></select> مقصد: <select class="form-select form-select-sm wh my-1" data-i="${i}">${whOptions(it.destination_warehouse_id)}</select> مبلغ کل: <span data-row-amount="${i}">${fmt(it.refund_amount)}</span></div></div>`)});$$('.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));summary();}
function renderInvoiceSummary(){const opt=$('#invoiceSelect')?.selectedOptions?.[0];$('#invoiceSummary').textContent=opt?.dataset?.summary||''}
$('#invoiceSelect').addEventListener('change',e=>{$('#invoiceId').value=e.target.value;state.invoice=e.target.value;state.items=[];renderItems();renderInvoiceSummary()});$('#openAddItem').onclick=()=>{if(state.type==='internal_invoice'){loadInvoiceItems().then(()=>new bootstrap.Modal($('#internalItemsModal')).show())}else{loadCategories(null);new bootstrap.Modal($('#sazehItemsModal')).show()}};$('#addSelectedInvoiceItems').onclick=()=>{$$('.invoice-pick:checked').forEach(cb=>{const it=JSON.parse(cb.dataset.item);if(state.items.some(x=>x.invoice_item_id===it.invoice_item_id))return;state.items.push({item_source:'invoice_item',invoice_item_id:it.invoice_item_id,product_id:it.product_id,product_variant_id:it.variant_id,product_name:it.product_name,variant_name:it.variant_name,sku:it.sku,barcode:it.barcode,sold_quantity:it.quantity,previously_returned:it.previously_returned,returnable:it.returnable,return_quantity:1,item_condition:'healthy',destination_warehouse_id:state.defaultDestinationWarehouseId||defaultWhFor('healthy'),refund_unit_price:it.unit_price,refund_amount:it.unit_price})});renderItems();bootstrap.Modal.getInstance($('#internalItemsModal')).hide()};$('#invoiceItemFilter').addEventListener('input',e=>{$$('#invoiceItemsBody tr').forEach(tr=>tr.classList.toggle('d-none',!tr.dataset.text.includes(e.target.value)))});$('#categoryResults')?.addEventListener('click',e=>{const el=e.target.closest('.cat-pick');if(!el)return;state.selectedCategories.push({id:el.dataset.id,name:el.dataset.name});$('#categoryPath').textContent=state.selectedCategories.map(c=>c.name).join(' > ');loadCategories(el.dataset.id);loadCategoryProducts();$('#variantCheckboxes').textContent='محصول را انتخاب کنید.'});$('#categoryProductSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>loadCategoryProducts(e.target.value),300)});$('#productSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>searchProducts(e.target.value),300)});document.addEventListener('click',e=>{const ps=e.target.closest('.product-select');if(ps)loadProductVariants(ps.dataset.id);if(e.target.id==='addPickedVariants')addSelectedVariants();if(e.target.classList.contains('rm')){state.items.splice(Number(e.target.dataset.i),1);renderItems()}});document.addEventListener('change',e=>{if(e.target.classList.contains('variant-pick')){const v=JSON.parse(e.target.dataset.variant), key=String(v.id);e.target.checked?state.selectedVariants.set(key,{variant:v,productId:e.target.dataset.productId,productName:e.target.dataset.productName}):state.selectedVariants.delete(key);$('#variantSelectedCount')&&($('#variantSelectedCount').textContent=state.selectedVariants.size)}});document.addEventListener('input',e=>{if(e.target.classList.contains('qty')){const i=Number(e.target.dataset.i),it=state.items[i];it.return_quantity=Number(e.target.value||1);updateRowAmount(i)}if(e.target.classList.contains('price')){const i=Number(e.target.dataset.i),it=state.items[i];it.refund_unit_price=rawNumber(e.target.value);updateRowAmount(i)}});document.addEventListener('focusin',e=>{if(e.target.classList.contains('price'))e.target.value=String(state.items[Number(e.target.dataset.i)]?.refund_unit_price||'')});document.addEventListener('focusout',e=>{if(e.target.classList.contains('price'))e.target.value=fmt(state.items[Number(e.target.dataset.i)]?.refund_unit_price||0)});document.addEventListener('change',e=>{if(e.target.classList.contains('cond')){const i=Number(e.target.dataset.i),it=state.items[i];it.item_condition=e.target.value;if(!it.destination_touched)it.destination_warehouse_id=state.defaultDestinationWarehouseId||defaultWhFor(e.target.value);renderItems()}if(e.target.classList.contains('wh')){const it=state.items[Number(e.target.dataset.i)];it.destination_warehouse_id=e.target.value;markManualDestination(it);renderItems()}});$('#defaultWarehouse').addEventListener('change',e=>{state.defaultDestinationWarehouseId=e.target.value;state.items.forEach(it=>{if(!it.destination_touched&&!it.destination_warehouse_id)it.destination_warehouse_id=e.target.value});renderItems()});$('#clearForm').onclick=()=>{if(confirm('فرم پاک شود؟')){state.items=[];renderItems()}};$('#applyButton').onclick=e=>{if(!confirm('ثبت نهایی موجودی و بستانکاری مشتری را تغییر می‌دهد. ادامه می‌دهید؟'))e.preventDefault()};syncExternalDateDisplay();$('#externalInvoiceDateFa')?.addEventListener('input',e=>syncExternalDateFromVisible(false));$('#salesReturnForm')?.addEventListener('submit',e=>{renderItems();if(!state.defaultDestinationWarehouseId){e.preventDefault();$('#defaultWarehouse')?.focus();alert('برای ادامه یک انبار مقصد واحد انتخاب کنید.');return}if(state.type==='sazeh_hesab'&&!syncExternalDateFromVisible(true)){e.preventDefault();$('#externalInvoiceDateFa')?.focus()}});syncSource();if(init.customerId)loadInvoices();renderItems();
})();
